import{_ as a,o,c as l,ag as r}from"./chunks/framework.CAXxHpAX.js";const c=JSON.parse('{"title":"新手入门路径","description":"","frontmatter":{},"headers":[],"relativePath":"30-学习路径/path-新手入门.md","filePath":"30-学习路径/path-新手入门.md","lastUpdated":null}'),e={name:"30-学习路径/path-新手入门.md"};function i(h,t,u,n,q,s){return o(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="新手入门路径" tabindex="-1">新手入门路径 <a class="header-anchor" href="#新手入门路径" aria-label="Permalink to &quot;新手入门路径&quot;">​</a></h1><blockquote><p>专为刚接触了空居士的学习者设计。 如果你对修行一无所知，从这里开始。</p></blockquote><hr><h2 id="学习节奏" tabindex="-1">学习节奏 <a class="header-anchor" href="#学习节奏" aria-label="Permalink to &quot;学习节奏&quot;">​</a></h2><p>这份指南按照&quot;一周入门&quot;的节奏设计。每天花20-30分钟，一周后你就有了清晰的修行方向。</p><hr><h2 id="第一天-认识了空居士" tabindex="-1">第一天：认识了空居士 <a class="header-anchor" href="#第一天-认识了空居士" aria-label="Permalink to &quot;第一天：认识了空居士&quot;">​</a></h2><h3 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h3><ul><li>知道了空居士是谁</li><li>了解他的教学风格</li><li>建立学习的信心</li></ul><h3 id="阅读" tabindex="-1">阅读 <a class="header-anchor" href="#阅读" aria-label="Permalink to &quot;阅读&quot;">​</a></h3><p><strong>1. 快速了解</strong>： 了空居士（蔡衍颛），现代实修者，融合禅宗、丹道、净土于一体。他的教学特点是：</p><ul><li><strong>口语化</strong>：不说玄妙的词，句句直指人心</li><li><strong>实践性</strong>：不空谈理论，每个道理都能在生活中用上</li><li><strong>自然</strong>：不搞神秘，不追求神通</li></ul><p><strong>2. 读三句关键的话</strong>：</p><blockquote><p>&quot;保持平静的要诀就是保持理智地去看待一切。&quot; &quot;不怕念起，只怕觉迟。&quot; &quot;做就是了。&quot;</p></blockquote><p><strong>3. 核心摘要快速浏览</strong>： <a href="/核心摘要">核心摘要</a> — 只看&quot;总纲&quot;和&quot;7大模型&quot;部分，5分钟</p><h3 id="今日实践" tabindex="-1">今日实践 <a class="header-anchor" href="#今日实践" aria-label="Permalink to &quot;今日实践&quot;">​</a></h3><ul><li>遇到不高兴的事，问自己：&quot;我为什么要不平静？&quot;</li></ul><hr><h2 id="第二天-心法入门——如何对待杂念" tabindex="-1">第二天：心法入门——如何对待杂念 <a class="header-anchor" href="#第二天-心法入门——如何对待杂念" aria-label="Permalink to &quot;第二天：心法入门——如何对待杂念&quot;">​</a></h2><h3 id="目标-1" tabindex="-1">目标 <a class="header-anchor" href="#目标-1" aria-label="Permalink to &quot;目标&quot;">​</a></h3><ul><li>理解&quot;不怕念起，只怕觉迟&quot;</li><li>学会基本的心法</li></ul><h3 id="阅读-1" tabindex="-1">阅读 <a class="header-anchor" href="#阅读-1" aria-label="Permalink to &quot;阅读&quot;">​</a></h3><p><strong>1. 关键认知</strong>：修行最大的误区就是以为&quot;要没杂念&quot;。 了空士说：<strong>有杂念是正常的</strong>。关键是——你知道自己有杂念，这就够了。</p><blockquote><p>&quot;走神了——让走神，知道走神就不走神。&quot;</p></blockquote><p><strong>2. 模型学习</strong>： 仔细阅读 [对境不住模型](/model-对境不住) 的前5个原子</p><p><strong>3. 专题阅读</strong>： [如何开始实修](/topic-入门实修) — 只看&quot;常见误区&quot;部分</p><h3 id="今日实践-1" tabindex="-1">今日实践 <a class="header-anchor" href="#今日实践-1" aria-label="Permalink to &quot;今日实践&quot;">​</a></h3><ul><li>白天观察自己：有多少次走神被我发现了？</li><li>发现了就走回来，不批评自己</li></ul><blockquote><p><strong>关键金句</strong>：&quot;不怕念起，只怕觉迟。&quot;</p></blockquote><hr><h2 id="第三天-第一次静坐" tabindex="-1">第三天：第一次静坐 <a class="header-anchor" href="#第三天-第一次静坐" aria-label="Permalink to &quot;第三天：第一次静坐&quot;">​</a></h2><h3 id="目标-2" tabindex="-1">目标 <a class="header-anchor" href="#目标-2" aria-label="Permalink to &quot;目标&quot;">​</a></h3><ul><li>完成人生第一次&quot;像样的&quot;静坐</li><li>体会&quot;似守非守&quot;</li></ul><h3 id="阅读-2" tabindex="-1">阅读 <a class="header-anchor" href="#阅读-2" aria-label="Permalink to &quot;阅读&quot;">​</a></h3><p>仔细阅读 [如何开始实修](/topic-入门实修) 的&quot;修行方法&quot;部分</p><h3 id="实践" tabindex="-1">实践 <a class="header-anchor" href="#实践" aria-label="Permalink to &quot;实践&quot;">​</a></h3><p><strong>静坐步骤（15分钟）</strong>：</p><ol><li><strong>姿势</strong>：找一把椅子坐下，背挺直但不僵硬，双手自然放在腿上</li><li><strong>放松</strong>：闭上眼睛，深呼吸3次，感受身体放松下来</li><li><strong>观照</strong>：轻轻地把注意力放在整个身体上，不要聚焦在某个点</li><li><strong>对待杂念</strong>：有念头来了，知道它来了，让它走，回到身体的感觉</li><li><strong>结束</strong>：慢慢睁开眼睛，活动一下手脚</li></ol><p><strong>要点</strong>：</p><ul><li>不要追求&quot;入静&quot;——知道自己在静坐就是静坐</li><li>不要追求&quot;感觉&quot;——发热、发麻都是正常，没有也正常</li><li>关键就是四个字：<strong>似守非守</strong>——轻轻知道，轻轻放下</li></ul><blockquote><p><strong>关键金句</strong>：&quot;不可用心守，不可无意求。&quot;</p></blockquote><hr><h2 id="第四天-情绪管理——第一次实战" tabindex="-1">第四天：情绪管理——第一次实战 <a class="header-anchor" href="#第四天-情绪管理——第一次实战" aria-label="Permalink to &quot;第四天：情绪管理——第一次实战&quot;">​</a></h2><h3 id="目标-3" tabindex="-1">目标 <a class="header-anchor" href="#目标-3" aria-label="Permalink to &quot;目标&quot;">​</a></h3><ul><li>用学到的道理处理今天的情绪</li><li>体会&quot;烦恼即菩提&quot;</li></ul><h3 id="阅读-3" tabindex="-1">阅读 <a class="header-anchor" href="#阅读-3" aria-label="Permalink to &quot;阅读&quot;">​</a></h3><p>[如何处理情绪](/topic-情绪) — 重点看&quot;三步法&quot;</p><h3 id="实践-1" tabindex="-1">实践 <a class="header-anchor" href="#实践-1" aria-label="Permalink to &quot;实践&quot;">​</a></h3><p>今天遇到让你生气或烦躁的事时，做三步：</p><ol><li><strong>停</strong>——深呼吸，心里说&quot;哦，我现在很生气&quot;</li><li><strong>看</strong>——观察这个情绪，它在你身体的哪个位置？什么感觉？</li><li><strong>放</strong>——问自己&quot;这个情绪对我有帮助吗？&quot;，如果没有，就让它走</li></ol><blockquote><p><strong>关键金句</strong>：&quot;情绪来了，不是压制它，也不是随它去。是——看清楚它，然后做该做的事。&quot;</p></blockquote><hr><h2 id="第五天-深入——选择你的方向" tabindex="-1">第五天：深入——选择你的方向 <a class="header-anchor" href="#第五天-深入——选择你的方向" aria-label="Permalink to &quot;第五天：深入——选择你的方向&quot;">​</a></h2><h3 id="目标-4" tabindex="-1">目标 <a class="header-anchor" href="#目标-4" aria-label="Permalink to &quot;目标&quot;">​</a></h3><ul><li>根据你生活中最困扰的问题，选择深入方向</li><li>了解背后的心法</li></ul><h3 id="阅读-4" tabindex="-1">阅读 <a class="header-anchor" href="#阅读-4" aria-label="Permalink to &quot;阅读&quot;">​</a></h3><p><strong>根据你的情况选择</strong>：</p><table tabindex="0"><thead><tr><th>如果你……</th><th>去读这个</th><th>帮助</th></tr></thead><tbody><tr><td>经常焦虑、担心</td><td>[如何面对焦虑](/topic-焦虑)</td><td>焦虑的三阶法</td></tr><tr><td>选什么都怕选错</td><td>[如何做出选择](/topic-选择)</td><td>四步决策法</td></tr><tr><td>和同事/家人处不好</td><td>[如何处理人际关系](/topic-人际关系)</td><td>三种原则</td></tr><tr><td>工作没动力、很累</td><td>[在工作中修行](/topic-工作修行)</td><td>工作即道场</td></tr><tr><td>有财富方面的困扰</td><td>[如何看待财富与布施](/topic-财富与布施)</td><td>取之有道，用之不执</td></tr></tbody></table><h3 id="实践-2" tabindex="-1">实践 <a class="header-anchor" href="#实践-2" aria-label="Permalink to &quot;实践&quot;">​</a></h3><ul><li>读完对应专题后，今天试着用里面的方法解决一个问题</li><li>不用全做到，做一步算一步</li></ul><blockquote><p><strong>关键金句</strong>：&quot;因上精进，果上随缘——过程努力，结果不执着。&quot;</p></blockquote><hr><h2 id="第六天-日常修行——将修行融入生活" tabindex="-1">第六天：日常修行——将修行融入生活 <a class="header-anchor" href="#第六天-日常修行——将修行融入生活" aria-label="Permalink to &quot;第六天：日常修行——将修行融入生活&quot;">​</a></h2><h3 id="目标-5" tabindex="-1">目标 <a class="header-anchor" href="#目标-5" aria-label="Permalink to &quot;目标&quot;">​</a></h3><ul><li>建立简单的日常修行习惯</li><li>理解&quot;家庭是道场&quot;</li></ul><h3 id="阅读-5" tabindex="-1">阅读 <a class="header-anchor" href="#阅读-5" aria-label="Permalink to &quot;阅读&quot;">​</a></h3><p><a href="/学习指南">学习指南</a> — 浏览各阶段概要</p><h3 id="建立小习惯" tabindex="-1">建立小习惯 <a class="header-anchor" href="#建立小习惯" aria-label="Permalink to &quot;建立小习惯&quot;">​</a></h3><p><strong>晨起（3分钟）</strong>：</p><ul><li>醒后不急着起床，躺一会儿，深呼吸3次</li><li>想一下&quot;今天我要做的主要事情是什么&quot;</li></ul><p><strong>白天</strong>：</p><ul><li>遇到不顺心的事→先深呼吸，再说话</li><li>等电梯/排队→轻轻返观身体</li><li>空闲时→默念几句&quot;阿弥陀佛&quot;</li></ul><p><strong>睡前（5-10分钟）</strong>：</p><ul><li>静坐或者只是安静躺着</li><li>捋一捋今天的念头：重要的想通，不重要的放下</li></ul><blockquote><p><strong>关键金句</strong>：&quot;家庭是道场，工作单位是道场，社会是道场。&quot;</p></blockquote><hr><h2 id="第七天-回顾与展望" tabindex="-1">第七天：回顾与展望 <a class="header-anchor" href="#第七天-回顾与展望" aria-label="Permalink to &quot;第七天：回顾与展望&quot;">​</a></h2><h3 id="目标-6" tabindex="-1">目标 <a class="header-anchor" href="#目标-6" aria-label="Permalink to &quot;目标&quot;">​</a></h3><ul><li>回顾一周收获</li><li>制定后续学习计划</li></ul><h3 id="回顾" tabindex="-1">回顾 <a class="header-anchor" href="#回顾" aria-label="Permalink to &quot;回顾&quot;">​</a></h3><p><strong>问自己三个问题</strong>：</p><ol><li>这一周我最大的收获是什么？</li><li>我遇到的哪个修行障碍最明显？</li><li>接下来我想重点学什么？</li></ol><h3 id="后续方向" tabindex="-1">后续方向 <a class="header-anchor" href="#后续方向" aria-label="Permalink to &quot;后续方向&quot;">​</a></h3><p><strong>方向A：继续深化</strong></p><ul><li>按 [认知路径](/30-学习路径/path-认知路径) 逐阶段学习</li><li>先重点消化&quot;对境不住&quot;和&quot;自然务实&quot;两个模型</li></ul><p><strong>方向B：解决问题</strong></p><ul><li>按 [问题路径](/30-学习路径/path-问题路径) 从你最困扰的问题入手</li><li>遇到新问题再回来查</li></ul><p><strong>方向C：实修深化</strong></p><ul><li>每天坚持静坐15-30分钟</li><li>研读 [性命双修模型](/model-性命双修)</li><li>尝试[修行进阶](/topic-修行进阶)中的十个月计划</li></ul><h3 id="推荐金句随身带" tabindex="-1">推荐金句随身带 <a class="header-anchor" href="#推荐金句随身带" aria-label="Permalink to &quot;推荐金句随身带&quot;">​</a></h3><p>选一句你最喜欢的话，写下来放在手机屏保或书桌前：</p><blockquote><p>&quot;做就是了。&quot; / &quot;不怕念起，只怕觉迟。&quot; / &quot;因上精进，果上随缘。&quot; / &quot;保持平静。&quot;</p></blockquote><hr><h2 id="常见新人疑问" tabindex="-1">常见新人疑问 <a class="header-anchor" href="#常见新人疑问" aria-label="Permalink to &quot;常见新人疑问&quot;">​</a></h2><h3 id="q-我静坐时完全静不下来-是不是不适合修行" tabindex="-1">Q：我静坐时完全静不下来，是不是不适合修行？ <a class="header-anchor" href="#q-我静坐时完全静不下来-是不是不适合修行" aria-label="Permalink to &quot;Q：我静坐时完全静不下来，是不是不适合修行？&quot;">​</a></h3><p><strong>A</strong>：杂念多是正常的。了空士说&quot;不怕念起，只怕觉迟&quot;——能发现自己在走神，就是进步。</p><h3 id="q-我需要双盘吗-单盘行不行" tabindex="-1">Q：我需要双盘吗？单盘行不行？ <a class="header-anchor" href="#q-我需要双盘吗-单盘行不行" aria-label="Permalink to &quot;Q：我需要双盘吗？单盘行不行？&quot;">​</a></h3><p><strong>A</strong>：椅子都可以。了空士说&quot;姿势中正安舒，不要硬撑&quot;——舒适比花样重要。</p><h3 id="q-修行要念什么经-背什么咒" tabindex="-1">Q：修行要念什么经？背什么咒？ <a class="header-anchor" href="#q-修行要念什么经-背什么咒" aria-label="Permalink to &quot;Q：修行要念什么经？背什么咒？&quot;">​</a></h3><p><strong>A</strong>：从《心经》开始，每天读一遍。但了空士说&quot;最重要的是——与人为善，观察自己的念头。&quot;</p><h3 id="q-我好像没有什么感觉-正常吗" tabindex="-1">Q：我好像没有什么感觉，正常吗？ <a class="header-anchor" href="#q-我好像没有什么感觉-正常吗" aria-label="Permalink to &quot;Q：我好像没有什么感觉，正常吗？&quot;">​</a></h3><p><strong>A</strong>：正常。不要追求感觉，也不要不相信有感觉。功夫到了自然有，不到不强求。</p><h3 id="q-我工作很忙-没时间修行怎么办" tabindex="-1">Q：我工作很忙，没时间修行怎么办？ <a class="header-anchor" href="#q-我工作很忙-没时间修行怎么办" aria-label="Permalink to &quot;Q：我工作很忙，没时间修行怎么办？&quot;">​</a></h3><p><strong>A</strong>：工作本身就是修行。了空士说&quot;家庭是道场，工作单位是道场&quot;——在你的日常中修，不必专门找时间。</p><hr><blockquote><p>创建日期：2026-05-06</p></blockquote>',106)])])}const p=a(e,[["render",i]]);export{c as __pageData,p as default};
